INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Abschluss eine eigenständige Phase im Projektmanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Beendet das Projekt"}, {"text": "Nein", "correct": false, "because": "Er ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Abschlussphase?', 3, '[{"text": "Projekt offiziell beenden", "correct": true, "because": "Schließt Arbeiten ab"}, {"text": "Neue Planung erstellen", "correct": false, "because": "Initiierungsschritt"}, {"text": "Team neu zusammenstellen", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Abschluss überprüft die Zielerreichung. b) Er erfolgt vor der Durchführung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nach Durchführung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aktivitäten gehören zur Abschlussphase?', 4, '[{"text": "Abnahme durch Stakeholder", "correct": true, "because": "Bestätigt Ergebnisse"}, {"text": "Unklare Berichte", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Dokumentation abschließen", "correct": true, "because": "Sichert Nachweis"}, {"text": "Erfahrungen reflektieren", "correct": true, "because": "Lessons Learned"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Abschlussphase erfolgreich enden?', 2, '[{"text": "Nein", "correct": true, "because": "Abnahme und Reflexion fehlen"}, {"text": "Ja", "correct": false, "because": "Unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Abschluss?', 3, '[{"text": "Projekt formal abschließen", "correct": true, "because": "Beendet Verpflichtungen"}, {"text": "Planung neu starten", "correct": false, "because": "Früherer Schritt"}, {"text": "Kosten neu kalkulieren", "correct": false, "because": "Controlling-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Abschluss nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen ihn"}, {"text": "Ja", "correct": false, "because": "Universelle Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe gehört zum Abschluss?', 3, '[{"text": "Ergebnisse präsentieren", "correct": true, "because": "Zeigt Erfolg"}, {"text": "Team neu einteilen", "correct": false, "because": "Anderer Fokus"}, {"text": "Zeitplan erstellen", "correct": false, "because": "Planungsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Abschluss dokumentiert Ergebnisse. b) Er ist immer problemlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Probleme möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Abschlussphase?', 3, '[{"text": "Projekt bleibt unklar beendet", "correct": true, "because": "Keine Abnahme"}, {"text": "Ergebnisse verbessern sich", "correct": false, "because": "Keine Reflexion"}, {"text": "Kosten sinken", "correct": false, "because": "Unklarheit bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Abschluss ohne Dokumentation erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Nachweis fehlt"}, {"text": "Ja", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Abschlussaktivität?', 3, '[{"text": "Abnahmeprotokoll erstellen", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas abschließen", "correct": false, "because": "Zu vage"}, {"text": "Team soll fertig sein", "correct": false, "because": "Keine spezifische Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Abschluss nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Stakeholder brauchen Ergebnisse"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Abschluss?', 4, '[{"text": "Ergebnisübergabe", "correct": true, "because": "Schließt Projekt ab"}, {"text": "Unklare Berichte", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Abschlussbericht", "correct": true, "because": "Dokumentiert Erfolg"}, {"text": "Feedbackrunde", "correct": true, "because": "Reflektiert Erfahrungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Abschluss dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode unterstützt den Abschluss?', 3, '[{"text": "Lessons Learned Workshop", "correct": true, "because": "Reflektiert Erfahrungen"}, {"text": "Keine Dokumentation", "correct": false, "because": "Fehlt Nachweis"}, {"text": "Zufällige Rückmeldung", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Abschluss ohne Stakeholder-Abnahme erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Abnahme bestätigt Erfolg"}, {"text": "Ja", "correct": false, "because": "Unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert den Abschluss?', 3, '[{"text": "Fehlende Dokumentation", "correct": true, "because": "Verhindert Nachweis"}, {"text": "Klare Abnahme", "correct": false, "because": "Fördert Abschluss"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Abschluss prüft Zielerreichung. b) Er ist nur für technische Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Abschlussphase?', 3, '[{"text": "Lernchancen für zukünftige Projekte", "correct": true, "because": "Reflektiert Erfahrungen"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Dokumentation", "correct": false, "because": "Fördert Nachweis"}]');
